import React, { useEffect, useRef, useState } from "react";
import { useDispatch } from "react-redux";
import FileUploadIcon from "@mui/icons-material/FileUpload";
import http, { uploadImage } from "../../services/utility";
import { apisPath } from "../../utils/path";
import { openSuccessTicker } from "../../redux/reducer/SuccessTickerReducer";
import { useLocation, useNavigate } from "react-router-dom";
import { openTicker } from "../../redux/reducer/ErrorTickerReducer";
import ArrowBackIcon from "@mui/icons-material/ArrowBack";
import { IconButton } from "@mui/material";

export default function AddNewBrand() {
  const navigate = useNavigate();
  const dispatch = useDispatch();
  const { state } = useLocation();
  const [brandData, setBrandData] = useState(state?.data);

  const newBrandRef = useRef(null);
  const newBrandBannerRef = useRef(null);
  const [brandName, setBrandName] = useState("");
  const [brandInfo, setBrandInfo] = useState("");
  const [brandImage, setBrandImage] = useState(null);
  const [brandBannerImage, setBrandBannerImage] = useState([]);
  const [cardData, setCardData] = useState([]);
  const [id, setId] = useState(null);

  useEffect(() => {
    if (brandData) {
      setBrandName(brandData?.name);
      setBrandImage(brandData?.image);
      setBrandBannerImage(brandData?.banner);
      setBrandInfo(brandData?.description);
      setId(brandData?.id);
    }
  }, [brandData, state]);

  const uploadData = async () => {
    const formData = {
      name: brandName,
      banner: brandBannerImage,
      image: brandImage,
      description: brandInfo,
    };

    if (id) {
      await http
        .put(`${apisPath?.admin?.brands}/${id}`, formData)
        .then((res) => {
          // console.log(res);
          dispatch(
            openSuccessTicker({ title: "Success", body: res?.data?.message })
          );
          navigate(-1);
        })
        .catch((err) => {
          // console.log(err);
          dispatch(
            openTicker({ title: "Error", body: err?.response?.data?.message })
          );
        });
    } else {
      await http
        .post(apisPath?.admin?.brands, formData)
        .then((res) => {
          // console.log(res);
          dispatch(
            openSuccessTicker({ title: "Success", body: res?.data?.message })
          );
          navigate(-1);
        })
        .catch((err) => {
          console.log(err);
          dispatch(
            openTicker({ title: "Error", body: err?.response?.data?.message })
          );
        });
    }
  };

  return (
    <div className="brands">
      <div className="detail__header">
        <IconButton
          aria-label="Back"
          className="back__button"
          onClick={() => navigate(-1)}
        >
          <ArrowBackIcon />
        </IconButton>
        <h3 className="page_heading">Brands</h3>
      </div>
      <div className="brands__content">
        <div className="brands__content__new_brand">
          <div className="brands__content__new_brand__images">
            <div
              className="brands__content__new_brand__images__upload_logo__skelaton"
              onClick={() => newBrandRef?.current?.click()}
            >
              {!brandImage ? (
                <>
                  <FileUploadIcon />
                  <span>Upload brand logo</span>
                  <small style={{ display: 'block', color: '#666', fontSize: '12px', marginTop: '5px' }}>
                    Recommended: 800x800px (Max 5MB, All Image Formats)
                  </small>
                </>
              ) : (
                <img src={brandImage} />
              )}
            </div>
            {brandBannerImage?.map((data, index) => {
              return (
                <div
                  className="brands__content__new_brand__images__upload_logo"
                  key={`add_brand_banner_${index}`}
                >
                  <img src={data} alt="Brand banner" />
                </div>
              );
            })}
            <div
              className="brands__content__new_brand__images__upload_logo__skelaton"
              onClick={() => newBrandBannerRef?.current?.click()}
            >
              <FileUploadIcon />
              <span>Upload brand banner</span>
              <small style={{ display: 'block', color: '#666', fontSize: '12px', marginTop: '5px' }}>
                Recommended: 1000x400px (Max 3MB, All Image Formats)
              </small>
            </div>
          </div>

          <input
            type="file"
            style={{ display: "none" }}
            ref={newBrandRef}
            accept="image/jpeg,image/jpg,image/png,image/gif,image/webp,image/svg+xml,image/bmp,image/tiff,image/x-icon"
            onChange={async (e) => {
                const file = e.target.files[0];
                if (file) {
                  // Check file size (5MB limit)
                  if (file.size > 5 * 1024 * 1024) {
                    dispatch(openTicker({ title: "Error", body: "File size should not exceed 5MB" }));
                    return;
                  }

                  // Check file type - allow comprehensive image formats
                  const allowedTypes = [
                    'image/jpeg', 'image/jpg', 'image/png', 'image/gif', 'image/webp',
                    'image/svg+xml', 'image/bmp', 'image/tiff', 'image/x-icon'
                  ];
                  if (!allowedTypes.includes(file.type)) {
                    dispatch(openTicker({ title: "Error", body: "Please select a valid image file (JPEG, PNG, GIF, WebP, SVG, BMP, TIFF, ICO)" }));
                    return;
                  }

                  // Check image dimensions
                  const img = new Image();
                  const objectUrl = URL.createObjectURL(file);

                  img.onload = async function() {
                    URL.revokeObjectURL(objectUrl);

                    // Check if dimensions are within acceptable range (only max dimensions)
                    const maxWidth = 1200;
                    const maxHeight = 1200;

                    if (img.width > maxWidth || img.height > maxHeight) {
                      dispatch(openTicker({
                        title: "Error",
                        body: `Image dimensions should not exceed ${maxWidth}x${maxHeight}px. Your image is ${img.width}x${img.height}px. Recommended: 800x800px`
                      }));
                      return;
                    }

              await uploadImage(e)
                .then((res) => {
                  setBrandImage(res?.url);
                })
                .catch((err) => {
                  console.log(err);
                });
                  };

                  img.onerror = function() {
                    URL.revokeObjectURL(objectUrl);
                    dispatch(openTicker({ title: "Error", body: "Invalid image file" }));
                  };

                  img.src = objectUrl;
                }
            }}
          />
          <input
            type="file"
            style={{ display: "none" }}
            ref={newBrandBannerRef}
            accept="image/jpeg,image/jpg,image/png,image/gif,image/webp,image/svg+xml,image/bmp,image/tiff,image/x-icon"
            onChange={async (e) => {
                const file = e.target.files[0];
                if (file) {
                  // Check file size (3MB limit)
                  if (file.size > 3 * 1024 * 1024) {
                    dispatch(openTicker({ title: "Error", body: "File size should not exceed 3MB" }));
                    return;
                  }

                  // Check file type - allow comprehensive image formats
                  const allowedTypes = [
                    'image/jpeg', 'image/jpg', 'image/png', 'image/gif', 'image/webp',
                    'image/svg+xml', 'image/bmp', 'image/tiff', 'image/x-icon'
                  ];
                  if (!allowedTypes.includes(file.type)) {
                    dispatch(openTicker({ title: "Error", body: "Please select a valid image file (JPEG, PNG, GIF, WebP, SVG, BMP, TIFF, ICO)" }));
                    return;
                  }

                  // Check image dimensions
                  const img = new Image();
                  const objectUrl = URL.createObjectURL(file);

                  img.onload = async function() {
                    URL.revokeObjectURL(objectUrl);

                    // Check if dimensions are within acceptable range for banner (only max dimensions)
                    const maxWidth = 1000;
                    const maxHeight = 400;

                    if (img.width > maxWidth || img.height > maxHeight) {
                      dispatch(openTicker({
                        title: "Error",
                        body: `Banner image dimensions should not exceed ${maxWidth}x${maxHeight}px. Your image is ${img.width}x${img.height}px. Recommended: 1000x400px`
                      }));
                      return;
                    }

              await uploadImage(e)
                .then((res) => {
                  setBrandBannerImage((prev) => [...prev, res?.url]);
                  newBrandBannerRef.current.value = "";
                })
                .catch((err) => {
                  console.log(err);
                });
                  };

                  img.onerror = function() {
                    URL.revokeObjectURL(objectUrl);
                    dispatch(openTicker({ title: "Error", body: "Invalid image file" }));
                  };

                  img.src = objectUrl;
                }
            }}
          />
          <div className="brands__content__new_brand__info">
            <div className="brands__content__new_brand__info__name">
              <label htmlFor="brand_name">Brand name</label>
            <input
              type="text"
              id="brand_name"
              name="brand_name"
              value={brandName}
              placeholder="Enter here"
              maxLength={50}
              onChange={(el) => setBrandName(el?.target?.value)}
            />
            <small style={{ color: '#666', fontSize: '12px' }}>
              {brandName?.length || 0}/50 characters
            </small>
            </div>
            <div className="brands__content__new_brand__info__info">
              <label htmlFor="brand_name">Brand Information</label>
              <textarea
                id="bodyText"
                name="bodyText"
                cols="100"
                rows="10"
                placeholder="Enter here"
                value={brandInfo}
                maxLength={500}
                onChange={(el) => setBrandInfo(el?.target?.value)}
              ></textarea>
              <small style={{ color: '#666', fontSize: '12px' }}>
                {brandInfo?.length || 0}/500 characters
              </small>
            </div>
            <button className="button-red" onClick={uploadData}>
              {id ? "Update brand" : "Add brand"}
            </button>
          </div>
        </div>
      </div>
    </div>
  );
}
